CREATE TABLE t AS SELECT i::INTEGER id FROM range(130000) r(i);
        CHECKPOINT;
        DELETE FROM t WHERE id=1 OR (id>=2048 AND id<4096) OR (id>=4096 AND id<6144 AND id%2=0) OR (id>=6144 AND id<8192 AND id<>7000) OR id=125000;
        CHECKPOINT;

